create or replace function private.immortal_exploration(s private.player_immortal_states)returns integer language sql immutable set search_path='' as $$select least(100,jsonb_array_length(s.investigated)*15+s.guide_stone_stage*10+case when s.outer_route_cleared then 25 else 0 end)$$;

create or replace function public.player_immortal_story_ack(p_channel text,p_story text,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());s private.player_immortal_states;a private.player_ascension_states;ready boolean:=false;required text[]:=array['platform-surveyed','first-expedition-return','second-dawn','exploration-seventy-five','guide-second-stage','third-dawn'];k text;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test')or p_story not in('platform-surveyed','first-expedition-return','second-dawn','exploration-seventy-five','guide-second-stage','third-dawn','platform-complete')or p_request_id is null then raise exception '仙界碑錄請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id)then raise exception '重複的仙界碑錄請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-immortal-story-'||p_channel));select * into s from private.player_immortal_states where user_id=uid and channel=p_channel for update;select * into a from private.player_ascension_states where user_id=uid and channel=p_channel;if s.user_id is null or not a.ascended then raise exception '尚未踏入仙界';end if;if s.story_flags?p_story then return private.immortal_snapshot(s);end if;ready:=case p_story when'platform-surveyed'then jsonb_array_length(s.investigated)>=3 when'first-expedition-return'then s.expedition_runs>=1 when'second-dawn'then now()>=s.timeline_started_at+interval'1 day'when'exploration-seventy-five'then private.immortal_exploration(s)>=75 when'guide-second-stage'then s.guide_stone_stage>=2 when'third-dawn'then now()>=s.timeline_started_at+interval'2 days'when'platform-complete'then s.guide_stone_stage>=3 and s.outer_route_cleared else false end;if p_story='platform-complete'then foreach k in array required loop ready:=ready and s.story_flags?k;end loop;end if;if not ready then raise exception '此篇仙界碑錄尚未顯現';end if;update private.player_immortal_states set story_flags=jsonb_set(story_flags,array[p_story],'true',true),platform_chapter_completed=platform_chapter_completed or p_story='platform-complete',revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload)values(uid,p_channel,s.revision,'immortal_story_acknowledged',p_request_id,jsonb_build_object('story',p_story));return private.immortal_snapshot(s);end$$;

create or replace function public.player_immortal_region_set(p_channel text,p_region text,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());s private.player_immortal_states;a private.player_ascension_states;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test')or p_region not in('ascension-platform','wuxi-wasteland')or p_request_id is null then raise exception '仙域切換請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id)then raise exception '重複的仙域切換請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-immortal-region-'||p_channel));select * into s from private.player_immortal_states where user_id=uid and channel=p_channel for update;select * into a from private.player_ascension_states where user_id=uid and channel=p_channel;if s.user_id is null or not a.ascended then raise exception '尚未踏入仙界';end if;if p_region='wuxi-wasteland'and not s.platform_chapter_completed then raise exception '飛升古臺篇尚未完成';end if;update private.player_immortal_states set region=p_region,wasteland_arrival_seen=wasteland_arrival_seen or p_region='wuxi-wasteland',revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload)values(uid,p_channel,s.revision,'immortal_region_set',p_request_id,jsonb_build_object('region',p_region));return private.immortal_snapshot(s);end$$;

create or replace function public.player_immortal_wasteland_route(p_channel text,p_route text,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());s private.player_immortal_states;a private.player_ascension_states;progress integer;gain_source integer;gain_trace integer;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test')or p_route not in('dryWind','sunken','kneeling')or p_request_id is null then raise exception '荒原遠征請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id)then raise exception '重複的荒原遠征請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-immortal-'||p_channel));select * into s from private.player_immortal_states where user_id=uid and channel=p_channel for update;select * into a from private.player_ascension_states where user_id=uid and channel=p_channel;if s.user_id is null or not a.ascended then raise exception '尚未踏入仙界';end if;if not s.platform_chapter_completed or s.guide_stone_stage<3 or not s.outer_route_cleared then raise exception '無息荒原尚未解鎖';end if;if(p_route='sunken'and coalesce((s.wasteland_route_progress->>'dryWind')::integer,0)<3)or(p_route='kneeling'and coalesce((s.wasteland_route_progress->>'sunken')::integer,0)<3)then raise exception '此荒原路線尚未發現';end if;if s.expedition_day is distinct from private.immortal_day()then s.expedition_day:=private.immortal_day();s.expedition_used:=0;end if;if s.expedition_used>=3 then raise exception '今日遠征次數已盡';end if;progress:=least(3,coalesce((s.wasteland_route_progress->>p_route)::integer,0)+1);gain_source:=case p_route when'dryWind'then 1 when'sunken'then 4 else 2 end;gain_trace:=case p_route when'dryWind'then 2 when'kneeling'then 1 else 0 end;update private.player_immortal_states set expedition_day=s.expedition_day,expedition_used=s.expedition_used+1,residual_source=residual_source+gain_source,barren_traces=barren_traces+gain_trace,wasteland_selected_route=p_route,wasteland_route_progress=jsonb_set(wasteland_route_progress,array[p_route],to_jsonb(progress),true),wasteland_story_flags=case when p_route='kneeling'and progress=1 then jsonb_set(wasteland_story_flags,'{kneelingAwoke}','true',true)else wasteland_story_flags end,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload)values(uid,p_channel,s.revision,'immortal_wasteland_route',p_request_id,jsonb_build_object('route',p_route,'progress',progress,'residualSource',gain_source,'barrenTraces',gain_trace));return private.immortal_snapshot(s);end$$;

revoke all on function private.immortal_exploration(private.player_immortal_states)from public,anon,authenticated;revoke execute on function public.player_immortal_story_ack(text,text,uuid),public.player_immortal_region_set(text,text,uuid)from public,anon;grant execute on function public.player_immortal_story_ack(text,text,uuid),public.player_immortal_region_set(text,text,uuid)to authenticated;
